const b = $input.first().json.body;
const type = b.type || 'booking';
const lang = (b.language || 'es').toLowerCase();
const name = b.patient_name || 'Paciente';
const email = String(b.patient_email || '');
const doc = b.doctor_name || '';
const spec = b.specialty || '';
const date = b.date || '';
const time = b.time || '';
const id = b.appointment_id || '';
const cp = '+34 91 345 17 57';
const ca = 'Calle Doctor Esquerdo 16, Madrid';
let sub = '', html = '';
if (lang === 'es') {
  if (type === 'booking') {
    sub = 'Cita confirmada - ' + id + ' | Clinica Masoumi';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#1d4ed8;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Clinica Masoumi</h2><p style="margin:4px 0 0;opacity:.85">Confirmacion de Cita</p></div><div style="padding:24px"><p>Hola <b>' + name + '</b>, su cita ha sido confirmada exitosamente.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb"><tr style="background:#f9fafb"><td style="padding:10px">Codigo</td><td style="padding:10px;font-weight:bold">' + id + '</td></tr><tr><td style="padding:10px">Doctor</td><td style="padding:10px">' + doc + '</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Especialidad</td><td style="padding:10px">' + spec + '</td></tr><tr><td style="padding:10px">Fecha</td><td style="padding:10px">' + date + '</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Hora</td><td style="padding:10px">' + time + '</td></tr><tr><td style="padding:10px">Duracion</td><td style="padding:10px">45 minutos</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Direccion</td><td style="padding:10px">' + ca + '</td></tr></table><p style="margin-top:16px">Para cancelar o reagendar llame al <b>' + cp + '</b>.</p></div><div style="background:#f3f4f6;padding:12px;text-align:center;font-size:12px;color:#9ca3af">Clinica Masoumi - ' + ca + '</div></div>';
  } else if (type === 'cancel') {
    sub = 'Cita cancelada | Clinica Masoumi';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px"><div style="background:#dc2626;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Clinica Masoumi</h2></div><div style="padding:24px"><p>Hola <b>' + name + '</b>, su cita con <b>' + doc + '</b> del <b>' + date + ' a las ' + time + '</b> ha sido cancelada correctamente.</p><p>Para nueva cita llame al <b>' + cp + '</b>.</p></div></div>';
  } else {
    sub = 'Cita reprogramada - ' + id + ' | Clinica Masoumi';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px"><div style="background:#059669;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Clinica Masoumi</h2></div><div style="padding:24px"><p>Hola <b>' + name + '</b>, su cita ha sido reprogramada para el <b>' + date + ' a las ' + time + '</b>. Codigo: <b>' + id + '</b>.</p><p>Para cambios llame al <b>' + cp + '</b>.</p></div></div>';
  }
} else {
  if (type === 'booking') {
    sub = 'Appointment Confirmed - ' + id + ' | Masoumi Clinic';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#1d4ed8;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2><p style="margin:4px 0 0;opacity:.85">Appointment Confirmation</p></div><div style="padding:24px"><p>Hello <b>' + name + '</b>, your appointment has been confirmed.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb"><tr style="background:#f9fafb"><td style="padding:10px">Code</td><td style="padding:10px;font-weight:bold">' + id + '</td></tr><tr><td style="padding:10px">Doctor</td><td style="padding:10px">' + doc + '</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Specialty</td><td style="padding:10px">' + spec + '</td></tr><tr><td style="padding:10px">Date</td><td style="padding:10px">' + date + '</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Time</td><td style="padding:10px">' + time + '</td></tr><tr><td style="padding:10px">Duration</td><td style="padding:10px">45 minutes</td></tr><tr style="background:#f9fafb"><td style="padding:10px">Address</td><td style="padding:10px">' + ca + '</td></tr></table><p style="margin-top:16px">To cancel or reschedule call <b>' + cp + '</b>.</p></div><div style="background:#f3f4f6;padding:12px;text-align:center;font-size:12px;color:#9ca3af">Masoumi Clinic - ' + ca + '</div></div>';
  } else if (type === 'cancel') {
    sub = 'Appointment Cancelled | Masoumi Clinic';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px"><div style="background:#dc2626;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2></div><div style="padding:24px"><p>Hello <b>' + name + '</b>, your appointment with <b>' + doc + '</b> on <b>' + date + ' at ' + time + '</b> has been cancelled.</p><p>To book a new appointment call <b>' + cp + '</b>.</p></div></div>';
  } else {
    sub = 'Appointment Rescheduled - ' + id + ' | Masoumi Clinic';
    html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px"><div style="background:#059669;color:#fff;padding:20px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2></div><div style="padding:24px"><p>Hello <b>' + name + '</b>, your appointment has been rescheduled to <b>' + date + ' at ' + time + '</b>. Code: <b>' + id + '</b>.</p><p>For changes call <b>' + cp + '</b>.</p></div></div>';
  }
}
return [{ json: { email_to: email, email_subject: sub, email_body: html, patient_name: name, type } }];
